"""Sanitized model card, architecture lineage, and read-only recruiter demo data."""
import json
from pathlib import Path

class PublicContentService:
    def __init__(self,cross,model_lab,historical,artifact_root="artifacts/cross_sectional"):
        self.cross,self.model_lab,self.historical,self.root=cross,model_lab,historical,Path(artifact_root)
    def model_card(self):
        manifest={}
        try:manifest=json.loads((self.root/"latest.json").read_text())
        except Exception:pass
        evaluation=self.model_lab.get_report() if self.model_lab.available else None
        return {"title":"Nexora Cross-Sectional Equity Ranking Model","objective":"Rank stocks by probability of outperforming SPY over the next 63 trading days.","training_universe":manifest.get("universe","S&P 500"),"label_definition":"1 when the stock's subsequent 63-trading-day return exceeds SPY; otherwise 0.","feature_families":["Multi-window technical and liquidity factors","Point-in-time SEC fundamentals when available","ALFRED macro regime context","FinBERT news intelligence when captured historically"],"evaluation_period":manifest.get("evaluation_period") or "Purged walk-forward folds across the available training history","data_sources":["Yahoo Finance market data","SEC EDGAR submissions and XBRL facts","FRED/ALFRED macro vintages","GDELT and Yahoo Finance news"],"leakage_controls":["63-trading-day purge and embargo","Date-wise cross-sectional ranks","SEC acceptance timestamps and reporting lags","ALFRED vintage dates","Forward outcomes joined only after prediction"],"known_biases":["Current S&P 500 membership can introduce survivorship bias when historical membership is unavailable","News coverage is greater for large-cap issuers","Provider revisions and corporate-action adjustments may alter historical market data"],"intended_uses":["Research prioritization","Paper-trading experiments","Model evaluation education"],"prohibited_uses":["Guaranteed return claims","Autonomous live-money trading","Personalized investment advice"],"limitations":["Historical associations may not persist","Probabilities are calibrated on historical folds","Sparse news and missing filings reduce evidence coverage"],"model_version":manifest.get("model_version"),"data_through":manifest.get("data_through"),"performance":evaluation}
    @staticmethod
    def architecture():return {"nodes":[{"id":"sources","label":"Market / SEC / News / FRED","layer":"sources"},{"id":"workers","label":"Ingestion Workers","layer":"ingestion"},{"id":"raw","label":"Raw Point-in-Time Data","layer":"data"},{"id":"features","label":"Feature Store","layer":"data"},{"id":"finbert","label":"FinBERT News Intelligence","layer":"model"},{"id":"training","label":"Purged Walk-Forward Training","layer":"model"},{"id":"registry","label":"Versioned Model Registry","layer":"model"},{"id":"scoring","label":"Daily Scoring Service","layer":"service"},{"id":"cache","label":"Redis SWR Cache","layer":"service"},{"id":"api","label":"Flask API","layer":"api"},{"id":"client","label":"React Client","layer":"client"}],"edges":[["sources","workers"],["workers","raw"],["raw","features"],["raw","finbert"],["features","training"],["training","registry"],["registry","scoring"],["finbert","scoring"],["scoring","cache"],["cache","api"],["api","client"]],"sample_lineage":{"output":"AAPL AI Score","model_artifact":"Versioned LightGBM + probability calibrator","feature_snapshot":"ticker/date keyed ranks","fundamental_source":"SEC accession + XBRL concept + acceptance timestamp","macro_source":"ALFRED realtime vintage","news_source":"Canonical article URL + FinBERT label"}}
    def demo(self):
        portfolio=[{"symbol":"AAPL","quantity":12,"average_cost":180,"market_price":195},{"symbol":"MSFT","quantity":7,"average_cost":405,"market_price":430},{"symbol":"NVDA","quantity":15,"average_cost":118,"market_price":142}];scores=[]
        for symbol in ("AAPL","MSFT","NVDA","TSLA"):
            try:scores.append({"symbol":symbol,**self.cross.get_score(symbol)})
            except Exception:scores.append({"symbol":symbol,"ai_score":None,"status":"artifact_unavailable"})
        return {"guest":True,"read_only":True,"paper_trading_enabled":False,"portfolio":portfolio,"scores":scores,"try_prompts":["Why is AAPL scored higher than MSFT?","What changed for NVDA this week?","Summarize Tesla's latest 10-Q."],"tours":["Open Model Lab to inspect walk-forward evidence","Open Architecture to trace a score to its sources","Use Historical Replay to inspect a past information set"]}
